monthlyInterestRate = InterestRatePercentage / 1200;
maxLoanAmount = maxMonthlyPayment * ((((1 + monthlyInterestRate) ^ termInMonths) - 1) / (monthlyInterestRate * ((1 + monthlyInterestRate) ^ termInMonths)));

