 termInMonths = termInyears * 12;
monthlyInterestRate = InterestRatePercentage / 1200;
maxLoanAmount = maxMonthlyPayment * ((1 - ((1 + monthlyInterestRate) ^ (-termInMonths))) / monthlyInterestRate)

